/**
 * Local vault audit script
 * Run this locally to compare .env.test values against your vault
 * without exposing values to external tools
 */

const fs = require('fs');
const crypto = require('crypto');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse variables
const lines = envContent.split('\n').filter(line => line.includes('='));

console.log('=== Vault Audit Report ===\n');
console.log('Compare these hashes against your vault:\n');

lines.forEach(line => {
  const [key, ...valueParts] = line.split('=');
