    const hash = crypto.createHash('sha256').update(value).digest('hex');
    console.log(`${key.trim()}:`);
    console.log(`  SHA-256: ${hash}`);
    console.log(`  Length: ${value.length} chars`);
    console.log(`  Prefix: ${value.substring(0, 8)}...`);
    console.log('');
  }
});

